src:
board [
  page [
    textbox id "heading" text "Workshop agenda" font-size LARGE {}
    group [
      section [
        textbox id "goal" text "Agree on the release scope" {}
      ] id "goals" name "Goals" {}
      section [
        sticky id "scope" text "Discuss scope" {}
        sticky id "risk" text "Review risks" {}
        sticky id "owner" text "Assign owners" {}
      ] id "topics" name "Topics" layout GRID columns 2 {}
    ] id "agenda-panels" layout ROW {}
  ] id "agenda" name "Agenda" layout COLUMN {}
] layout-profile FIGJAM_V1 {}..

board [ page [
  sticky id "s" text "" fill "#fc0" opacity 50 font-size LARGE {}
  shape id "sh" text "Shape" kind ENG_DATABASE fill "white" stroke "#112233" stroke-width THICK opacity 80 font-size SMALL {}
  textbox id "t" text "Line one\nLine two" color "gray" font-size HUGE {}
  connector id "c" from "s" to "t" label "" stroke "red" stroke-width THICK opacity 40 font-size MEDIUM line-style DASHED from-cap CIRCLE_FILLED to-cap TRIANGLE_FILLED {}
] id "p1" name "Page" background "#eeeeee" layout GRID columns 2 {} ] title "All" show-page-tabs true show-page-menu true layout-profile FIGJAM_V1 {}..

board [ page [
  sticky id "d" text "Loose idea" {}
  shape id "a" text "Start" kind ELLIPSE {}
  shape id "b" text "Build" {}
  shape id "c" text "Ship" kind ROUNDED_RECTANGLE {}
  sticky id "e" text "Another loose idea" {}
  connector id "a-b" from "a" to "b" {}
  connector id "b-c" from "b" to "c" {}
] id "p1" name "Mixed" {} ] {}..

board [ page [
  section [ sticky id "a" text "A" {} ] id "left" name "Left" before ["right"] {}
  section [ sticky id "b" text "B" {} ] id "right" name "Right" {}
  connector id "ab" from "a" to "b" {}
] id "p1" name "Page" layout FLOW direction DOWN {} ] {}..

board [
  page [
    sticky id "first" text "First page" {}
  ] id "week-1" name "Notes" {}
  page [
    sticky id "second" text "Second page" {}
    textbox id "caption" text "A textbox wide enough to wrap onto a second line in FigJam" {}
  ] id "week-2" name "Notes" layout COLUMN {}
] {}..

board [ page [
  section [ ] id "ideas" name "Ideas" {}
  group [ ] id "spare" {}
] id "p1" name "Template" layout ROW {}
page [ ] id "p2" name "Empty page" {} ] title "Workshop" {}..

board [ page [
  group [ sticky id "b" text "Second, declared first" {} ] id "g2" {}
  group [ sticky id "a" text "First" {} ] id "g1" {}
  connector id "a-b" from "a" to "b" label "then" {}
] id "p1" name "Lifted" layout FLOW {} ] {}..

board [
  page [
    shape id "fetch" text "Fetch data" kind ROUNDED_RECTANGLE before ["valid"] {}
    shape id "valid" text "Valid?" kind DIAMOND before ["save" "error"] {}
    shape id "save" text "Save result" kind ROUNDED_RECTANGLE {}
    shape id "error" text "Report error" kind ROUNDED_RECTANGLE {}
    connector id "fetch-valid" from "fetch" to "valid" {}
    connector id "valid-save" from "valid" to "save" label "Yes" {}
    connector id "valid-error" from "valid" to "error" label "No" {}
    connector id "retry" from "error" to "fetch" label "Retry" line-style DASHED {}
  ] id "processing" name "Processing" layout FLOW direction RIGHT {}
] layout-profile FIGJAM_V1 {}..

board [ page [
  shape id "one" text "One" before ["two"] {}
  shape id "two" text "Two" {}
  section [
    sticky id "low" text "Bottom" before ["high"] {}
    sticky id "high" text "Top" {}
  ] id "climb" name "Climb" layout FLOW direction UP {}
] id "p1" name "Reversed" layout FLOW direction LEFT {} ] {}..

board [
  page [ sticky id "a" text "A" {} connector id "ab" from "a" to "b" {} ] id "p1" name "One" {}
  page [ sticky id "b" text "B" {} ] id "p2" name "Two" {}
] {}..

board [
  page [ ] id "p1" name "One" {}
  page [ ] id "p2" name "Two" {}
] show-page-tabs false {}..

board [ page [
  sticky id "a" text "A" before ["b"] {}
  sticky id "b" text "B" before ["c"] {}
  sticky id "c" text "C" before ["a"] {}
] id "p1" name "Page" layout FLOW {} ] {}..

board [
  page [
    shape id "a" text "A" before ["b"] {}
    shape id "b" text "B" before ["a"] {}
  ] id "cycle" name "Invalid order" layout FLOW {}
] layout-profile FIGJAM_V1 {}..

board [ page [
  section [
    sticky id "intro" text "Intro" {}
  ] id "task-section" name "task" {}
  shape id "task" text "Task" {}
  connector id "intro-task" from "intro" to "task" label "next" {}
  connector id "task-loop" from "task" to "task" label "retry" from-cap CIRCLE_FILLED to-cap TRIANGLE_FILLED {}
] id "p1" name "Collision" layout ROW {} ] {}..

board [ page [
  shape id "client" text "Client" {}
  shape id "server" text "Server" {}
  connector id "req" from "client" to "server" label "request" {}
  connector id "res" from "server" to "client" label "response" {}
  connector id "ping" from "client" to "server" label "heartbeat" line-style DASHED {}
] id "p1" name "Parallel" layout ROW {} ] {}..

board [
  page [
    sticky id "idea" text "Idea" {}
    sticky id "plan" text "Plan" {}
    connector id "idea-plan" from "idea" to "plan" label "develop" {}
  ] id "planning" name "Planning" layout FLOW direction RIGHT {}
] title "Planning board" layout-profile FIGJAM_V1 {}..

board [ page [
  sticky id "short" text "Ship" {}
  sticky id "long" text "Pairing helped us resolve the integration issues quickly" {}
  shape id "decide" text "Is the integration environment ready for the release candidate?" kind DIAMOND {}
  textbox id "emoji" text "Launch 🚀 day" font-size LARGE {}
] id "p1" name "Remeasure" layout ROW {} ] {}..

board [ page [
  sticky id "n1" text "1" {} sticky id "n2" text "2" {} sticky id "n3" text "3" {}
  sticky id "n4" text "4" {} sticky id "mid" text "Middle" {} sticky id "n6" text "6" {}
  sticky id "n7" text "7" {} sticky id "n8" text "8" {} sticky id "n9" text "9" {}
  connector id "again" from "mid" to "mid" label "Again and again" font-size LARGE {}
] id "p1" name "Repair" layout GRID columns 3 {} ] {}..

board [
  page [
    section [
      sticky id "shipped" text "Shipped on time" fill "green" {}
      sticky id "pairing" text "Pairing helped us resolve the integration issues" fill "green" {}
    ] id "went-well" name "Went well" layout COLUMN {}
    section [
      sticky id "flaky" text "Flaky tests delayed release verification" fill "pink" {}
    ] id "improve" name "To improve" layout COLUMN {}
    section [
      sticky id "quarantine" text "Quarantine flaky tests and assign owners" fill "blue" {}
    ] id "actions" name "Action items" layout COLUMN {}
  ] id "retro" name "Sprint retrospective" layout ROW {}
] title "Sprint retrospective" layout-profile FIGJAM_V1 {}..

board [ page [
  shape id "a" text "A" {}
  shape id "b" text "B" {}
  connector id "loop" from "a" to "a" label "again" {}
  connector id "ab1" from "a" to "b" label "first" {}
  connector id "ab2" from "a" to "b" label "second" {}
] id "p1" name "Graph" layout FLOW {} ] {}..

board [ page [
  shape id "a" text "A" stroke-width THICK {}
  shape id "b" text "B" stroke-width THICK {}
  shape id "c" text "C" stroke-width THICK {}
  connector id "a-c" from "a" to "c" stroke-width THICK label "skips B" {}
  connector id "a-b" from "a" to "b" stroke-width THICK {}
] id "p1" name "Thick" layout ROW {} ] {}..
